      await processIssue(issue, template);
    } catch (e) {
      console.error(`  Error processing issue #${issue.number}:`, e.message);
    }
  }

  console.log('Done.');
}

main().catch(e => {
  console.error('Fatal error:', e);
  process.exit(1);
